package com.rulecraft.decisionops.decisionapi;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.persistence.DecisionServiceRepository;import com.rulecraft.decisionops.decisionapi.domain.DecisionApiRequest;import com.rulecraft.decisionops.decisionapi.persistence.DecisionApiRequestRepository;import com.rulecraft.decisionops.decisionapi.security.DecisionApiPrincipal;import com.rulecraft.decisionops.deployment.CapturedDecisionRuntime;import com.rulecraft.decisionops.deployment.domain.RuntimeDeploymentState;import com.rulecraft.decisionops.deployment.persistence.*;import com.rulecraft.decisionops.explainability.ExplainabilityService;import com.rulecraft.decisionops.explainability.ExplainabilityService.*;import com.rulecraft.decisionops.explainability.domain.TraceChannel;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.core.JacksonException;import tools.jackson.databind.*;import tools.jackson.databind.node.*;

@Service public class DecisionApiEvaluationService {private final RuntimeEnvironmentRepository environments;private final RuntimeDeploymentRepository deployments;private final DecisionServiceRepository services;private final DecisionApiRequestRepository requests;private final DecisionApiEvidenceStore evidence;private final CapturedDecisionRuntime runtime;private final ExplainabilityService explainability;private final ProjectAccessPolicy access;private final CatalogService catalog;private final AuditService audit;private final ObjectMapper mapper;private final Clock clock;public DecisionApiEvaluationService(RuntimeEnvironmentRepository environments,RuntimeDeploymentRepository deployments,DecisionServiceRepository services,DecisionApiRequestRepository requests,DecisionApiEvidenceStore evidence,CapturedDecisionRuntime runtime,ExplainabilityService explainability,ProjectAccessPolicy access,CatalogService catalog,AuditService audit,ObjectMapper mapper,Clock clock){this.environments=environments;this.deployments=deployments;this.services=services;this.requests=requests;this.evidence=evidence;this.runtime=runtime;this.explainability=explainability;this.access=access;this.catalog=catalog;this.audit=audit;this.mapper=mapper;this.clock=clock;}
@Transactional public SingleResponse single(DecisionApiPrincipal principal,String serviceKey,SingleCommand command){route(principal,serviceKey);validateRequest(command==null?null:command.requestId());var subject=subject(principal);var hash=hash(command);var retry=retry(principal.tenantId(),principal.serviceId(),subject,command.requestId(),"SINGLE",hash,SingleResponse.class);if(retry!=null)return retry;var active=active(principal.tenantId(),principal.projectId(),principal.serviceId());var inputs=command.inputs()==null?Map.<String,JsonNode>of():command.inputs();var evaluationId=evaluationId(active,subject,command.requestId(),hash,"single");var context=trace(principal.tenantId(),principal.projectId(),principal.serviceId(),principal.credentialId(),null,principal.keyPrefix(),command.requestId(),null,TraceChannel.API_SINGLE,active,evaluationId);var started=System.nanoTime();CapturedDecisionRuntime.Evaluation evaluated;try{evaluated=runtime.evaluate(active.artifact(),inputs);explainability.record(explainability.success(context,inputs,evaluated,(System.nanoTime()-started)/1000));}catch(DomainProblemException failure){explainability.record(explainability.failure(context,inputs,failure.getCode(),failure.getMessage(),(System.nanoTime()-started)/1000));throw failure;}var response=new SingleResponse(command.requestId(),evaluationId,serviceKey,active.deploymentId(),active.versionId(),active.fingerprint(),evaluated.outputs());response=persist(principal.tenantId(),principal.projectId(),principal.serviceId(),principal.credentialId(),subject,command.requestId(),"SINGLE",hash,active,1,response,SingleResponse.class);audit.record(principal.tenantId(),null,"DECISION_API_EVALUATED","RUNTIME_DEPLOYMENT",response.deploymentId(),Map.of("credentialId",principal.credentialId(),"requestId",command.requestId(),"serviceId",principal.serviceId(),"outputCount",response.outputs().size()));return response;}
@Transactional public BatchResponse batch(DecisionApiPrincipal principal,String serviceKey,BatchCommand command){route(principal,serviceKey);return batch(principal.tenantId(),principal.projectId(),principal.serviceId(),principal.credentialId(),subject(principal),principal.keyPrefix(),serviceKey,command,null);}@Transactional public BatchResponse batchSession(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,BatchCommand command){access.requireVisible(actor,projectId);var service=catalog.getService(actor,projectId,serviceId);return batch(actor.tenantId(),projectId,serviceId,null,"USER:"+actor.userId(),actor.displayName(),service.serviceKey(),command,actor);}@Transactional(readOnly=true)public List<RequestView> history(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);return requests.findTop50ByTenantIdAndProjectIdAndServiceIdOrderByCreatedAtDesc(actor.tenantId(),projectId,serviceId).stream().map(this::view).toList();}
private BatchResponse batch(UUID tenantId,UUID projectId,UUID serviceId,UUID credentialId,String subject,String subjectLabel,String serviceKey,BatchCommand command,RuleCraftPrincipal actor){validateBatch(command);var requestHash=hash(command);var retry=retry(tenantId,serviceId,subject,command.requestId(),"BATCH",requestHash,BatchResponse.class);if(retry!=null)return retry;var active=active(tenantId,projectId,serviceId);var results=new ArrayList<BatchItemResponse>();var captures=new ArrayList<Capture>();var channel=credentialId==null?TraceChannel.WORKBENCH_BATCH:TraceChannel.API_BATCH;int succeeded=0;for(var item:command.items()){var inputs=item.inputs()==null?Map.<String,JsonNode>of():item.inputs();var id=evaluationId(active,subject,command.requestId(),requestHash,item.correlationId());var context=trace(tenantId,projectId,serviceId,credentialId,actor==null?null:actor.userId(),subjectLabel,command.requestId(),item.correlationId(),channel,active,id);var started=System.nanoTime();try{var evaluated=runtime.evaluate(active.artifact(),inputs);captures.add(explainability.success(context,inputs,evaluated,(System.nanoTime()-started)/1000));results.add(new BatchItemResponse(item.correlationId(),true,id,evaluated.outputs(),null,null));succeeded++;}catch(DomainProblemException failure){captures.add(explainability.failure(context,inputs,failure.getCode(),failure.getMessage(),(System.nanoTime()-started)/1000));results.add(new BatchItemResponse(item.correlationId(),false,id,null,failure.getCode(),safe(failure.getMessage())));}catch(RuntimeException failure){captures.add(explainability.failure(context,inputs,"RC-API-EVALUATION-FAILED","The decision could not be evaluated. Review the request or active deployment.",(System.nanoTime()-started)/1000));results.add(new BatchItemResponse(item.correlationId(),false,id,null,"RC-API-EVALUATION-FAILED","The decision could not be evaluated. Review the request or active deployment."));}}explainability.recordAll(captures);var status=succeeded==results.size()?"SUCCEEDED":succeeded==0?"FAILED":"PARTIAL";var response=new BatchResponse(command.requestId(),serviceKey,active.deploymentId(),active.versionId(),active.fingerprint(),status,succeeded,results.size()-succeeded,results);response=persist(tenantId,projectId,serviceId,credentialId,subject,command.requestId(),"BATCH",requestHash,active,results.size(),response,BatchResponse.class);audit.record(tenantId,actor==null?null:actor.userId(),"DECISION_API_BATCH_EVALUATED","RUNTIME_DEPLOYMENT",response.deploymentId(),Map.of("credentialId",credentialId==null?"SESSION":credentialId,"requestId",command.requestId(),"serviceId",serviceId,"items",response.items().size(),"succeeded",response.succeededCount()));return response;}
private void validateBatch(BatchCommand command){validateRequest(command==null?null:command.requestId());if(command.items()==null||command.items().isEmpty())bad("RC-API-BATCH-EMPTY","Provide at least one batch item.");if(command.items().size()>100)bad("RC-API-BATCH-LIMIT","A batch can contain at most 100 evaluations.");var ids=new HashSet<String>();for(var item:command.items()){var id=item==null||item.correlationId()==null?"":item.correlationId().strip();if(id.isBlank()||id.length()>80||!ids.add(id))bad("RC-API-BATCH-CORRELATION","Each batch item needs a unique correlation ID of 1–80 characters.");}}private void validateRequest(UUID id){if(id==null)bad("RC-API-REQUEST-ID","Provide a request ID so retries remain idempotent.");}private void route(DecisionApiPrincipal principal,String serviceKey){var service=services.findByIdAndTenantIdAndProjectId(principal.serviceId(),principal.tenantId(),principal.projectId()).orElseThrow(this::routeNotFound);if(serviceKey==null||!service.getServiceKey().equalsIgnoreCase(serviceKey))throw routeNotFound();}private Active active(UUID tenantId,UUID projectId,UUID serviceId){var environment=environments.findByServiceIdAndTenantIdAndProjectId(serviceId,tenantId,projectId).orElseThrow(()->conflict("RC-API-NO-ACTIVE","This decision service has no active runtime deployment."));if(environment.getActiveDeploymentId()==null)throw conflict("RC-API-NO-ACTIVE","This decision service has no active runtime deployment.");var deployment=deployments.findByIdAndServiceIdAndTenantIdAndProjectId(environment.getActiveDeploymentId(),serviceId,tenantId,projectId).orElseThrow(()->conflict("RC-API-ACTIVE-MISSING","The active runtime deployment is unavailable."));if(deployment.getState()!=RuntimeDeploymentState.ACTIVE)throw conflict("RC-API-ACTIVE-STATE","The runtime environment is not active.");return new Active(deployment.getId(),deployment.getDecisionVersionId(),deployment.getArtifactFingerprint(),deployment.getArtifactJson());}
private <T>T retry(UUID tenantId,UUID serviceId,String subject,UUID requestId,String operation,String requestHash,Class<T> type){var existing=requests.findByTenantIdAndServiceIdAndSubjectKeyAndClientRequestId(tenantId,serviceId,subject,requestId);if(existing.isEmpty())return null;var value=existing.get();if(!value.getOperation().equals(operation)||!MessageDigest.isEqual(value.getRequestHash().getBytes(StandardCharsets.UTF_8),requestHash.getBytes(StandardCharsets.UTF_8)))throw conflict("RC-API-REQUEST-CONFLICT","This request ID was already used with different content.");return read(value.getResponseJson(),type);}private <T>T persist(UUID tenantId,UUID projectId,UUID serviceId,UUID credentialId,String subject,UUID requestId,String operation,String requestHash,Active active,int count,T response,Class<T> type){var now=Instant.now(clock);try{evidence.store(new DecisionApiRequest(tenantId,projectId,serviceId,credentialId,subject,requestId,operation,requestHash,active.deploymentId(),active.versionId(),active.fingerprint(),count,json(response),now));return response;}catch(DataIntegrityViolationException race){var existing=evidence.load(tenantId,serviceId,subject,requestId).orElseThrow(()->race);if(!existing.getOperation().equals(operation)||!existing.getRequestHash().equals(requestHash))throw conflict("RC-API-REQUEST-CONFLICT","This request ID was already used with different content.");return read(existing.getResponseJson(),type);}}
private TraceContext trace(UUID tenantId,UUID projectId,UUID serviceId,UUID credentialId,UUID actorId,String label,UUID requestId,String correlationId,TraceChannel channel,Active active,UUID evaluationId){return new TraceContext(evaluationId,tenantId,projectId,serviceId,active.deploymentId(),active.versionId(),credentialId,actorId,label,requestId,correlationId,channel,active.fingerprint());}private UUID evaluationId(Active active,String subject,UUID requestId,String requestHash,String item){return UUID.nameUUIDFromBytes((active.deploymentId()+":"+subject+":"+requestId+":"+requestHash+":"+item).getBytes(StandardCharsets.UTF_8));}private String hash(Object value){return ApiCredentialService.hash(json(sort(mapper.valueToTree(value))));}private JsonNode sort(JsonNode value){if(value==null||value.isNull())return NullNode.getInstance();if(value.isObject()){var result=mapper.createObjectNode();value.propertyNames().stream().sorted().forEach(key->result.set(key,sort(value.get(key))));return result;}if(value.isArray()){var result=mapper.createArrayNode();value.values().forEach(item->result.add(sort(item)));return result;}return value;}private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JacksonException failure){throw new IllegalStateException("Decision API evidence could not be serialized.",failure);}}private <T>T read(String value,Class<T> type){try{return mapper.readValue(value,type);}catch(JacksonException failure){throw new IllegalStateException("Persisted decision API evidence is invalid.",failure);}}private String subject(DecisionApiPrincipal principal){return "KEY:"+principal.credentialId();}private String safe(String value){if(value==null)return "Evaluation failed.";return value.length()>600?value.substring(0,600):value;}private RequestView view(DecisionApiRequest value){return new RequestView(value.getId(),value.getClientRequestId(),value.getOperation(),value.getDeploymentId(),value.getDecisionVersionId(),value.getArtifactFingerprint(),value.getItemCount(),value.getCreatedAt());}private void bad(String code,String detail){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,detail);}private DomainProblemException conflict(String code,String detail){return new DomainProblemException(HttpStatus.CONFLICT,code,detail);}private DomainProblemException routeNotFound(){return new DomainProblemException(HttpStatus.NOT_FOUND,"RC-API-SERVICE-NOT-FOUND","Decision endpoint not found.");}
private record Active(UUID deploymentId,UUID versionId,String fingerprint,String artifact){}public record SingleCommand(UUID requestId,Map<String,JsonNode> inputs){}public record SingleResponse(UUID requestId,UUID evaluationId,String serviceKey,UUID deploymentId,UUID decisionVersionId,String artifactFingerprint,Map<String,JsonNode> outputs){}public record BatchItem(String correlationId,Map<String,JsonNode> inputs){}public record BatchCommand(UUID requestId,List<BatchItem> items){}public record BatchItemResponse(String correlationId,boolean succeeded,UUID evaluationId,Map<String,JsonNode> outputs,String errorCode,String errorDetail){}public record BatchResponse(UUID requestId,String serviceKey,UUID deploymentId,UUID decisionVersionId,String artifactFingerprint,String status,int succeededCount,int failedCount,List<BatchItemResponse> items){}public record RequestView(UUID id,UUID requestId,String operation,UUID deploymentId,UUID decisionVersionId,String artifactFingerprint,int itemCount,Instant createdAt){}
}
